python3 -c "
import json
with open('/app/resources/treasury_bulletin_1970_05.json', 'r') as f:
    data = json.load(f)
# Print keys
def print_keys(d, prefix=''):
    if isinstance(d, dict):
        for k, v in d.items():
            print(f'{prefix}{k}')
            if isinstance(v, (dict, list)):
                print_keys(v, prefix + '  ')
    elif isinstance(d, list) and len(d) > 0:
        print_keys(d[0], prefix + '[0] ')
print_keys(data)
" 2>&1 | head -100
